-- Consultas de validação ELT x ETL (ELT-08)
-- Geradas pelo notebook notebooks/elt/08_validacao.ipynb

-- contagem_etl_elt
SELECT 'dim_tempo' AS tabela, (SELECT COUNT(*) FROM public.dim_tempo) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_tempo) AS linhas_elt
UNION ALL SELECT 'dim_gravidade' AS tabela, (SELECT COUNT(*) FROM public.dim_gravidade) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_gravidade) AS linhas_elt
UNION ALL SELECT 'dim_perfil_vitima' AS tabela, (SELECT COUNT(*) FROM public.dim_perfil_vitima) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_perfil_vitima) AS linhas_elt
UNION ALL SELECT 'dim_transporte' AS tabela, (SELECT COUNT(*) FROM public.dim_transporte) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_transporte) AS linhas_elt
UNION ALL SELECT 'dim_localidade' AS tabela, (SELECT COUNT(*) FROM public.dim_localidade) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_localidade) AS linhas_elt
UNION ALL SELECT 'dim_via' AS tabela, (SELECT COUNT(*) FROM public.dim_via) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_via) AS linhas_elt
UNION ALL SELECT 'dim_profissao' AS tabela, (SELECT COUNT(*) FROM public.dim_profissao) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_profissao) AS linhas_elt
UNION ALL SELECT 'dim_local_obito' AS tabela, (SELECT COUNT(*) FROM public.dim_local_obito) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.dim_local_obito) AS linhas_elt
UNION ALL SELECT 'fato_pessoa_sinistro' AS tabela, (SELECT COUNT(*) FROM public.fato_pessoa_sinistro) AS linhas_etl, (SELECT COUNT(*) FROM dw_elt.fato_pessoa_sinistro) AS linhas_elt;

-- obitos_etl_elt
SELECT 'ETL' AS origem, SUM(flag_obito) AS obitos, COUNT(*) AS vitimas FROM public.fato_pessoa_sinistro
UNION ALL
SELECT 'ELT', SUM(flag_obito), COUNT(*) FROM dw_elt.fato_pessoa_sinistro;

-- fk_sem_correspondencia_elt
SELECT 'sk_data_sinistro -> dim_tempo' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_tempo d ON f.sk_data_sinistro = d.sk_tempo WHERE d.sk_tempo IS NULL
UNION ALL SELECT 'sk_data_obito -> dim_tempo' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_tempo d ON f.sk_data_obito = d.sk_tempo WHERE d.sk_tempo IS NULL
UNION ALL SELECT 'sk_gravidade -> dim_gravidade' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_gravidade d ON f.sk_gravidade = d.sk_gravidade WHERE d.sk_gravidade IS NULL
UNION ALL SELECT 'sk_perfil_vitima -> dim_perfil_vitima' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_perfil_vitima d ON f.sk_perfil_vitima = d.sk_perfil_vitima WHERE d.sk_perfil_vitima IS NULL
UNION ALL SELECT 'sk_transporte -> dim_transporte' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_transporte d ON f.sk_transporte = d.sk_transporte WHERE d.sk_transporte IS NULL
UNION ALL SELECT 'sk_localidade -> dim_localidade' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_localidade d ON f.sk_localidade = d.sk_localidade WHERE d.sk_localidade IS NULL
UNION ALL SELECT 'sk_via -> dim_via' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_via d ON f.sk_via = d.sk_via WHERE d.sk_via IS NULL
UNION ALL SELECT 'sk_profissao -> dim_profissao' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_profissao d ON f.sk_profissao = d.sk_profissao WHERE d.sk_profissao IS NULL
UNION ALL SELECT 'sk_local_obito -> dim_local_obito' AS chave, COUNT(*) AS orfaos FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_local_obito d ON f.sk_local_obito = d.sk_local_obito WHERE d.sk_local_obito IS NULL;

-- except_dim_tempo
SELECT 'dim_tempo' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "data"::text AS "data", "ano"::text AS "ano", "trimestre"::text AS "trimestre", "mes"::text AS "mes", "nome_mes"::text AS "nome_mes", "dia"::text AS "dia", "ano_mes"::text AS "ano_mes", "dia_semana"::text AS "dia_semana", "nome_dia_semana"::text AS "nome_dia_semana", "fim_de_semana"::text AS "fim_de_semana", "feriado"::text AS "feriado", "nome_feriado"::text AS "nome_feriado" FROM public.dim_tempo EXCEPT SELECT "data"::text AS "data", "ano"::text AS "ano", "trimestre"::text AS "trimestre", "mes"::text AS "mes", "nome_mes"::text AS "nome_mes", "dia"::text AS "dia", "ano_mes"::text AS "ano_mes", "dia_semana"::text AS "dia_semana", "nome_dia_semana"::text AS "nome_dia_semana", "fim_de_semana"::text AS "fim_de_semana", "feriado"::text AS "feriado", "nome_feriado"::text AS "nome_feriado" FROM dw_elt.dim_tempo) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "data"::text AS "data", "ano"::text AS "ano", "trimestre"::text AS "trimestre", "mes"::text AS "mes", "nome_mes"::text AS "nome_mes", "dia"::text AS "dia", "ano_mes"::text AS "ano_mes", "dia_semana"::text AS "dia_semana", "nome_dia_semana"::text AS "nome_dia_semana", "fim_de_semana"::text AS "fim_de_semana", "feriado"::text AS "feriado", "nome_feriado"::text AS "nome_feriado" FROM dw_elt.dim_tempo EXCEPT SELECT "data"::text AS "data", "ano"::text AS "ano", "trimestre"::text AS "trimestre", "mes"::text AS "mes", "nome_mes"::text AS "nome_mes", "dia"::text AS "dia", "ano_mes"::text AS "ano_mes", "dia_semana"::text AS "dia_semana", "nome_dia_semana"::text AS "nome_dia_semana", "fim_de_semana"::text AS "fim_de_semana", "feriado"::text AS "feriado", "nome_feriado"::text AS "nome_feriado" FROM public.dim_tempo) b) AS so_na_elt;

-- except_dim_gravidade
SELECT 'dim_gravidade' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "gravidade_lesao"::text AS "gravidade_lesao", "nivel_gravidade"::text AS "nivel_gravidade" FROM public.dim_gravidade EXCEPT SELECT "gravidade_lesao"::text AS "gravidade_lesao", "nivel_gravidade"::text AS "nivel_gravidade" FROM dw_elt.dim_gravidade) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "gravidade_lesao"::text AS "gravidade_lesao", "nivel_gravidade"::text AS "nivel_gravidade" FROM dw_elt.dim_gravidade EXCEPT SELECT "gravidade_lesao"::text AS "gravidade_lesao", "nivel_gravidade"::text AS "nivel_gravidade" FROM public.dim_gravidade) b) AS so_na_elt;

-- except_dim_perfil_vitima
SELECT 'dim_perfil_vitima' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "sexo"::text AS "sexo", "faixa_etaria_demografica"::text AS "faixa_etaria_demografica", "faixa_etaria_legal"::text AS "faixa_etaria_legal", "nacionalidade"::text AS "nacionalidade", "grau_de_instrucao"::text AS "grau_de_instrucao" FROM public.dim_perfil_vitima EXCEPT SELECT "sexo"::text AS "sexo", "faixa_etaria_demografica"::text AS "faixa_etaria_demografica", "faixa_etaria_legal"::text AS "faixa_etaria_legal", "nacionalidade"::text AS "nacionalidade", "grau_de_instrucao"::text AS "grau_de_instrucao" FROM dw_elt.dim_perfil_vitima) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "sexo"::text AS "sexo", "faixa_etaria_demografica"::text AS "faixa_etaria_demografica", "faixa_etaria_legal"::text AS "faixa_etaria_legal", "nacionalidade"::text AS "nacionalidade", "grau_de_instrucao"::text AS "grau_de_instrucao" FROM dw_elt.dim_perfil_vitima EXCEPT SELECT "sexo"::text AS "sexo", "faixa_etaria_demografica"::text AS "faixa_etaria_demografica", "faixa_etaria_legal"::text AS "faixa_etaria_legal", "nacionalidade"::text AS "nacionalidade", "grau_de_instrucao"::text AS "grau_de_instrucao" FROM public.dim_perfil_vitima) b) AS so_na_elt;

-- except_dim_transporte
SELECT 'dim_transporte' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "tipo_de_vitima"::text AS "tipo_de_vitima", "modo_transporte_vitima"::text AS "modo_transporte_vitima", "tipo_veiculo_vitima"::text AS "tipo_veiculo_vitima" FROM public.dim_transporte EXCEPT SELECT "tipo_de_vitima"::text AS "tipo_de_vitima", "modo_transporte_vitima"::text AS "modo_transporte_vitima", "tipo_veiculo_vitima"::text AS "tipo_veiculo_vitima" FROM dw_elt.dim_transporte) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "tipo_de_vitima"::text AS "tipo_de_vitima", "modo_transporte_vitima"::text AS "modo_transporte_vitima", "tipo_veiculo_vitima"::text AS "tipo_veiculo_vitima" FROM dw_elt.dim_transporte EXCEPT SELECT "tipo_de_vitima"::text AS "tipo_de_vitima", "modo_transporte_vitima"::text AS "modo_transporte_vitima", "tipo_veiculo_vitima"::text AS "tipo_veiculo_vitima" FROM public.dim_transporte) b) AS so_na_elt;

-- except_dim_localidade
SELECT 'dim_localidade' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "cod_ibge"::text AS "cod_ibge", "municipio"::text AS "municipio", "regiao_administrativa"::text AS "regiao_administrativa" FROM public.dim_localidade EXCEPT SELECT "cod_ibge"::text AS "cod_ibge", "municipio"::text AS "municipio", "regiao_administrativa"::text AS "regiao_administrativa" FROM dw_elt.dim_localidade) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "cod_ibge"::text AS "cod_ibge", "municipio"::text AS "municipio", "regiao_administrativa"::text AS "regiao_administrativa" FROM dw_elt.dim_localidade EXCEPT SELECT "cod_ibge"::text AS "cod_ibge", "municipio"::text AS "municipio", "regiao_administrativa"::text AS "regiao_administrativa" FROM public.dim_localidade) b) AS so_na_elt;

-- except_dim_via
SELECT 'dim_via' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "tipo_via"::text AS "tipo_via", "local_via"::text AS "local_via" FROM public.dim_via EXCEPT SELECT "tipo_via"::text AS "tipo_via", "local_via"::text AS "local_via" FROM dw_elt.dim_via) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "tipo_via"::text AS "tipo_via", "local_via"::text AS "local_via" FROM dw_elt.dim_via EXCEPT SELECT "tipo_via"::text AS "tipo_via", "local_via"::text AS "local_via" FROM public.dim_via) b) AS so_na_elt;

-- except_dim_profissao
SELECT 'dim_profissao' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "profissao"::text AS "profissao", "grupo_profissao"::text AS "grupo_profissao" FROM public.dim_profissao EXCEPT SELECT "profissao"::text AS "profissao", "grupo_profissao"::text AS "grupo_profissao" FROM dw_elt.dim_profissao) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "profissao"::text AS "profissao", "grupo_profissao"::text AS "grupo_profissao" FROM dw_elt.dim_profissao EXCEPT SELECT "profissao"::text AS "profissao", "grupo_profissao"::text AS "grupo_profissao" FROM public.dim_profissao) b) AS so_na_elt;

-- except_dim_local_obito
SELECT 'dim_local_obito' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "local_obito"::text AS "local_obito" FROM public.dim_local_obito EXCEPT SELECT "local_obito"::text AS "local_obito" FROM dw_elt.dim_local_obito) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "local_obito"::text AS "local_obito" FROM dw_elt.dim_local_obito EXCEPT SELECT "local_obito"::text AS "local_obito" FROM public.dim_local_obito) b) AS so_na_elt;

-- except_fato_pessoa_sinistro
SELECT 'fato_pessoa_sinistro' AS tabela,
  (SELECT COUNT(*) FROM (SELECT "id_pessoa"::text AS "id_pessoa", "id_sinistro"::text AS "id_sinistro", "id_veiculo"::text AS "id_veiculo", "idade"::text AS "idade", "dias_ate_obito"::text AS "dias_ate_obito", "flag_obito"::text AS "flag_obito", "qtd_pessoas"::text AS "qtd_pessoas" FROM public.fato_pessoa_sinistro EXCEPT SELECT "id_pessoa"::text AS "id_pessoa", "id_sinistro"::text AS "id_sinistro", "id_veiculo"::text AS "id_veiculo", "idade"::text AS "idade", "dias_ate_obito"::text AS "dias_ate_obito", "flag_obito"::text AS "flag_obito", "qtd_pessoas"::text AS "qtd_pessoas" FROM dw_elt.fato_pessoa_sinistro) a) AS so_na_etl,
  (SELECT COUNT(*) FROM (SELECT "id_pessoa"::text AS "id_pessoa", "id_sinistro"::text AS "id_sinistro", "id_veiculo"::text AS "id_veiculo", "idade"::text AS "idade", "dias_ate_obito"::text AS "dias_ate_obito", "flag_obito"::text AS "flag_obito", "qtd_pessoas"::text AS "qtd_pessoas" FROM dw_elt.fato_pessoa_sinistro EXCEPT SELECT "id_pessoa"::text AS "id_pessoa", "id_sinistro"::text AS "id_sinistro", "id_veiculo"::text AS "id_veiculo", "idade"::text AS "idade", "dias_ate_obito"::text AS "dias_ate_obito", "flag_obito"::text AS "flag_obito", "qtd_pessoas"::text AS "qtd_pessoas" FROM public.fato_pessoa_sinistro) b) AS so_na_elt;

-- soma_verificacao_fato
SELECT 'public' AS esquema, COUNT(*) AS linhas, SUM(hashtextextended(concat_ws('|', COALESCE(f."id_pessoa"::text, '~'), COALESCE(f."id_sinistro"::text, '~'), COALESCE(f."id_veiculo"::text, '~'), COALESCE(f."idade"::text, '~'), COALESCE(f."dias_ate_obito"::text, '~'), COALESCE(f."flag_obito"::text, '~'), COALESCE(f."qtd_pessoas"::text, '~'), COALESCE(d_data_sinistro."data"::text, '~'), COALESCE(d_data_sinistro."ano"::text, '~'), COALESCE(d_data_sinistro."trimestre"::text, '~'), COALESCE(d_data_sinistro."mes"::text, '~'), COALESCE(d_data_sinistro."nome_mes"::text, '~'), COALESCE(d_data_sinistro."dia"::text, '~'), COALESCE(d_data_sinistro."ano_mes"::text, '~'), COALESCE(d_data_sinistro."dia_semana"::text, '~'), COALESCE(d_data_sinistro."nome_dia_semana"::text, '~'), COALESCE(d_data_sinistro."fim_de_semana"::text, '~'), COALESCE(d_data_sinistro."feriado"::text, '~'), COALESCE(d_data_sinistro."nome_feriado"::text, '~'), COALESCE(d_data_obito."data"::text, '~'), COALESCE(d_data_obito."ano"::text, '~'), COALESCE(d_data_obito."trimestre"::text, '~'), COALESCE(d_data_obito."mes"::text, '~'), COALESCE(d_data_obito."nome_mes"::text, '~'), COALESCE(d_data_obito."dia"::text, '~'), COALESCE(d_data_obito."ano_mes"::text, '~'), COALESCE(d_data_obito."dia_semana"::text, '~'), COALESCE(d_data_obito."nome_dia_semana"::text, '~'), COALESCE(d_data_obito."fim_de_semana"::text, '~'), COALESCE(d_data_obito."feriado"::text, '~'), COALESCE(d_data_obito."nome_feriado"::text, '~'), COALESCE(d_gravidade."gravidade_lesao"::text, '~'), COALESCE(d_gravidade."nivel_gravidade"::text, '~'), COALESCE(d_perfil_vitima."sexo"::text, '~'), COALESCE(d_perfil_vitima."faixa_etaria_demografica"::text, '~'), COALESCE(d_perfil_vitima."faixa_etaria_legal"::text, '~'), COALESCE(d_perfil_vitima."nacionalidade"::text, '~'), COALESCE(d_perfil_vitima."grau_de_instrucao"::text, '~'), COALESCE(d_transporte."tipo_de_vitima"::text, '~'), COALESCE(d_transporte."modo_transporte_vitima"::text, '~'), COALESCE(d_transporte."tipo_veiculo_vitima"::text, '~'), COALESCE(d_localidade."cod_ibge"::text, '~'), COALESCE(d_localidade."municipio"::text, '~'), COALESCE(d_localidade."regiao_administrativa"::text, '~'), COALESCE(d_via."tipo_via"::text, '~'), COALESCE(d_via."local_via"::text, '~'), COALESCE(d_profissao."profissao"::text, '~'), COALESCE(d_profissao."grupo_profissao"::text, '~'), COALESCE(d_local_obito."local_obito"::text, '~')), 0)::numeric)::text AS soma_hash FROM public.fato_pessoa_sinistro f LEFT JOIN public.dim_tempo d_data_sinistro ON f.sk_data_sinistro = d_data_sinistro.sk_tempo LEFT JOIN public.dim_tempo d_data_obito ON f.sk_data_obito = d_data_obito.sk_tempo LEFT JOIN public.dim_gravidade d_gravidade ON f.sk_gravidade = d_gravidade.sk_gravidade LEFT JOIN public.dim_perfil_vitima d_perfil_vitima ON f.sk_perfil_vitima = d_perfil_vitima.sk_perfil_vitima LEFT JOIN public.dim_transporte d_transporte ON f.sk_transporte = d_transporte.sk_transporte LEFT JOIN public.dim_localidade d_localidade ON f.sk_localidade = d_localidade.sk_localidade LEFT JOIN public.dim_via d_via ON f.sk_via = d_via.sk_via LEFT JOIN public.dim_profissao d_profissao ON f.sk_profissao = d_profissao.sk_profissao LEFT JOIN public.dim_local_obito d_local_obito ON f.sk_local_obito = d_local_obito.sk_local_obito
UNION ALL
SELECT 'dw_elt' AS esquema, COUNT(*) AS linhas, SUM(hashtextextended(concat_ws('|', COALESCE(f."id_pessoa"::text, '~'), COALESCE(f."id_sinistro"::text, '~'), COALESCE(f."id_veiculo"::text, '~'), COALESCE(f."idade"::text, '~'), COALESCE(f."dias_ate_obito"::text, '~'), COALESCE(f."flag_obito"::text, '~'), COALESCE(f."qtd_pessoas"::text, '~'), COALESCE(d_data_sinistro."data"::text, '~'), COALESCE(d_data_sinistro."ano"::text, '~'), COALESCE(d_data_sinistro."trimestre"::text, '~'), COALESCE(d_data_sinistro."mes"::text, '~'), COALESCE(d_data_sinistro."nome_mes"::text, '~'), COALESCE(d_data_sinistro."dia"::text, '~'), COALESCE(d_data_sinistro."ano_mes"::text, '~'), COALESCE(d_data_sinistro."dia_semana"::text, '~'), COALESCE(d_data_sinistro."nome_dia_semana"::text, '~'), COALESCE(d_data_sinistro."fim_de_semana"::text, '~'), COALESCE(d_data_sinistro."feriado"::text, '~'), COALESCE(d_data_sinistro."nome_feriado"::text, '~'), COALESCE(d_data_obito."data"::text, '~'), COALESCE(d_data_obito."ano"::text, '~'), COALESCE(d_data_obito."trimestre"::text, '~'), COALESCE(d_data_obito."mes"::text, '~'), COALESCE(d_data_obito."nome_mes"::text, '~'), COALESCE(d_data_obito."dia"::text, '~'), COALESCE(d_data_obito."ano_mes"::text, '~'), COALESCE(d_data_obito."dia_semana"::text, '~'), COALESCE(d_data_obito."nome_dia_semana"::text, '~'), COALESCE(d_data_obito."fim_de_semana"::text, '~'), COALESCE(d_data_obito."feriado"::text, '~'), COALESCE(d_data_obito."nome_feriado"::text, '~'), COALESCE(d_gravidade."gravidade_lesao"::text, '~'), COALESCE(d_gravidade."nivel_gravidade"::text, '~'), COALESCE(d_perfil_vitima."sexo"::text, '~'), COALESCE(d_perfil_vitima."faixa_etaria_demografica"::text, '~'), COALESCE(d_perfil_vitima."faixa_etaria_legal"::text, '~'), COALESCE(d_perfil_vitima."nacionalidade"::text, '~'), COALESCE(d_perfil_vitima."grau_de_instrucao"::text, '~'), COALESCE(d_transporte."tipo_de_vitima"::text, '~'), COALESCE(d_transporte."modo_transporte_vitima"::text, '~'), COALESCE(d_transporte."tipo_veiculo_vitima"::text, '~'), COALESCE(d_localidade."cod_ibge"::text, '~'), COALESCE(d_localidade."municipio"::text, '~'), COALESCE(d_localidade."regiao_administrativa"::text, '~'), COALESCE(d_via."tipo_via"::text, '~'), COALESCE(d_via."local_via"::text, '~'), COALESCE(d_profissao."profissao"::text, '~'), COALESCE(d_profissao."grupo_profissao"::text, '~'), COALESCE(d_local_obito."local_obito"::text, '~')), 0)::numeric)::text AS soma_hash FROM dw_elt.fato_pessoa_sinistro f LEFT JOIN dw_elt.dim_tempo d_data_sinistro ON f.sk_data_sinistro = d_data_sinistro.sk_tempo LEFT JOIN dw_elt.dim_tempo d_data_obito ON f.sk_data_obito = d_data_obito.sk_tempo LEFT JOIN dw_elt.dim_gravidade d_gravidade ON f.sk_gravidade = d_gravidade.sk_gravidade LEFT JOIN dw_elt.dim_perfil_vitima d_perfil_vitima ON f.sk_perfil_vitima = d_perfil_vitima.sk_perfil_vitima LEFT JOIN dw_elt.dim_transporte d_transporte ON f.sk_transporte = d_transporte.sk_transporte LEFT JOIN dw_elt.dim_localidade d_localidade ON f.sk_localidade = d_localidade.sk_localidade LEFT JOIN dw_elt.dim_via d_via ON f.sk_via = d_via.sk_via LEFT JOIN dw_elt.dim_profissao d_profissao ON f.sk_profissao = d_profissao.sk_profissao LEFT JOIN dw_elt.dim_local_obito d_local_obito ON f.sk_local_obito = d_local_obito.sk_local_obito;
